# BEGIN_C_BLOCK block_id=pc-non-specific-or-unbound-scan-2ef39cea kind=example title="Bind variables via scan and always use $var after binding"
{
  "plan": [
    { "type": "scan", "target": "WaterSource", "out": "water_location" },
    { "type": "while", "condition": { "type": "notnear", "target": "$water_location" }, "body": [
      { "type": "move", "target": "$water_location" }
    ]},
    { "type": "take", "target": "$water_location" }
  ]
}
# END_C_BLOCK block_id=pc-non-specific-or-unbound-scan-2ef39cea

# BEGIN_C_BLOCK block_id=pc-goal-mismatch-missing-action-1fb5ba1d kind=example title="Every step advances the main goal directly"
{
  "plan": [
    { "type": "scan", "target": "Berries", "out": "berries_loc" },
    { "type": "while", "condition": { "type": "notnear", "target": "$berries_loc" }, "body": [
      { "type": "move", "target": "$berries_loc" }
    ]},
    { "type": "take", "target": "$berries_loc" },
    { "type": "use", "target": "$berries_loc", "reason": "eat to reduce hunger" }
  ]
}
# END_C_BLOCK block_id=pc-goal-mismatch-missing-action-1fb5ba1d

# BEGIN_C_BLOCK block_id=pc-inefficient-or-extra-actions-54c09c36 kind=example title="Minimal direct path: No redundant movement or checks"
{
  "plan": [
    { "type": "scan", "target": "Stick", "out": "stick_loc" },
    { "type": "while", "condition": { "type": "notnear", "target": "$stick_loc" }, "body": [
      { "type": "move", "target": "$stick_loc" }
    ]},
    { "type": "take", "target": "$stick_loc" }
  ]
}
# END_C_BLOCK block_id=pc-inefficient-or-extra-actions-54c09c36

# BEGIN_C_BLOCK block_id=pc-missing-precondition-for-action-37f4d2c7 kind=example title="Precondition checked: Near before take/use/inspect"
{
  "plan": [
    { "type": "scan", "target": "Apple", "out": "apple_loc" },
    { "type": "while", "condition": { "type": "notnear", "target": "$apple_loc" }, "body": [
      { "type": "move", "target": "$apple_loc" }
    ]},
    { "type": "inspect", "target": "$apple_loc", "reason": "quality check" },
    { "type": "take", "target": "$apple_loc" }
  ]
}
# END_C_BLOCK block_id=pc-missing-precondition-for-action-37f4d2c7
